import {createPlayer} from './player.js';
import {createSelectorSound} from './selector-sound.js';
export function createJukebox(config,onStatus){
 const videos=config.videos,button=document.querySelector('#video-selector'),label=button.querySelector('span'),mark=button.querySelector('path'),surface=document.querySelector('.performance'),ratio=document.querySelector('.player-ratio'),sound=createSelectorSound(config.soundEnabled!==false);
 let index=0,generation=0,player=null,abort=null,started=false,ready=false,busy=true,requested=false,lastError=null,requestTimer=0,transitionTimer=0,disposed=false,lastInteraction=-Infinity;
 const current=()=>videos[index];
 function render(){const next=started;button.dataset.mode=next?'next':'play';label.textContent=next?'NEXT':'PLAY';button.setAttribute('aria-label',next?'Next video':'Play video');button.disabled=busy||requested;mark.setAttribute('d',next?'M6 5 16 12 6 19ZM18 5v14':'M8 5 19 12 8 19Z');button.setAttribute('aria-busy',String(busy||requested));}
 function status(value,token){if(disposed||token!==generation)return;lastError=value.error;ready=value.ready;if(value.state==='playing'){started=true;requested=false;clearTimeout(requestTimer);}if(['error','awaiting-gesture'].includes(value.state)){requested=false;busy=false;clearTimeout(requestTimer);}if(value.ready||value.state==='error'){busy=false;surface.classList.remove('video-changing');}render();onStatus({...value,index,generation,selector:started?'next':'play'},current());}
 async function install(token){if(disposed||token!==generation)return;document.querySelector('#video-title').textContent=current().title;document.querySelector('#creator-name').textContent=current().creator;document.title=(config.machineTitle||current().creator)+' — Epicentre';ratio.replaceChildren(Object.assign(document.createElement('div'),{id:'youtube-player'}));const next=await createPlayer(current(),v=>status(v,token),{signal:abort.signal});if(token!==generation||disposed)next.destroy();else player=next;}
 function select(nextIndex,{animate=false}={}){generation++;const token=generation;clearTimeout(requestTimer);clearTimeout(transitionTimer);player?.stop();abort?.abort();player?.destroy();player=null;abort=new AbortController();index=(nextIndex+videos.length)%videos.length;started=false;ready=false;busy=true;requested=false;lastError=null;render();document.dispatchEvent(new CustomEvent('splatters-video:video-changed',{detail:{id:current().id,videoId:current().videoId,index}}));if(animate&&!matchMedia('(prefers-reduced-motion: reduce)').matches){surface.classList.add('video-changing');transitionTimer=setTimeout(()=>install(token),150);}else install(token);}
 function next(){if(busy||disposed||performance.now()-lastInteraction<450)return false;lastInteraction=performance.now();sound.play();button.classList.remove('channel-pulse');void button.offsetWidth;button.classList.add('channel-pulse');select(index+1,{animate:true});return true;}
 function play(){if(busy||requested||disposed||performance.now()-lastInteraction<450)return false;lastInteraction=performance.now();if(lastError||!ready){select(index);return false;}requested=true;render();if(!player?.play()){requested=false;render();return false;}requestTimer=setTimeout(()=>{if(requested){requested=false;render();onStatus({state:'awaiting-gesture',error:'Use YouTube’s native Play control if this browser blocks external playback.',ready,videoId:current().videoId,index,generation},current());}},6000);return true;}
 const click=()=>started?next():play();button.addEventListener('click',click);select(0);
 return{next,play,snapshot:()=>({index,id:current().id,videoId:current().videoId,mode:started?'next':'play',generation,started,ready,busy,requested,error:lastError,catalogueSize:videos.length,sound:sound.snapshot()}),playerSnapshot:()=>player?.snapshot()||null,destroy(){disposed=true;generation++;clearTimeout(requestTimer);clearTimeout(transitionTimer);abort?.abort();player?.destroy();sound.destroy();button.removeEventListener('click',click);}};
}
